1	import {
2	  AggregateParamErrors,
3	  ArgumentsHost,
4	  BadRequestException,
5	  Body,
6	  CanActivate,
7	  Catch,
8	  ConflictException,
9	  Controller,
10	  createParamDecorator,
11	  DefaultValuePipe,
12	  ExecutionContext,
13	  ExceptionFilter,
14	  ForbiddenException,
15	  Get,
16	  Headers,
17	  HttpException,
18	  HttpStatus,
19	  Injectable,
20	  NotFoundException,
21	  Param,
22	  PipeTransform,
23	  Post,
24	  Query,
25	  UseFilters,
26	  UseGuards,
27	} from '@nestjs/common';
28	import { HttpAdapterHost } from '@nestjs/core';
29	
30	/**
31	 * Per-process counters used by the request-isolation suites. The aggregation
32	 * state itself is per-request; these counters only let tests observe how many
33	 * pipes/handlers ran for a sequence of requests. They are reset in every test's
34	 * beforeEach via {@link resetIsolationState}.
35	 */
36	export const isolationState: {
37	  pipeCalls: string[];
38	  handlerCalls: Record<string, number>;
39	} = {
40	  pipeCalls: [],
41	  handlerCalls: {},
42	};
43	
44	export function resetIsolationState(): void {
45	  isolationState.pipeCalls = [];
46	  isolationState.handlerCalls = {};
47	  MyParamFilter.received = [];
48	  MyWideFilter.last = null;
49	}
50	
51	function recordHandler(name: string): void {
52	  isolationState.handlerCalls[name] =
53	    (isolationState.handlerCalls[name] ?? 0) + 1;
54	}
55	
56	class NumberPipe implements PipeTransform<string, number> {
57	  constructor(private readonly errorMessage: string) {}
58	
59	  transform(value: string): number {
60	    isolationState.pipeCalls.push(this.errorMessage);
61	    const parsed = Number(value);
62	    if (Number.isNaN(parsed) || value.trim() === '') {
63	      throw new BadRequestException(this.errorMessage);
64	    }
65	    return parsed;
66	  }
67	}
68	
69	class SlowNumberPipe implements PipeTransform<
70	  string,
71	  Promise<number> | number
72	> {
73	  constructor(
74	    private readonly errorMessage: string,
75	    private readonly delayMs: number,
76	  ) {}
77	
78	  async transform(value: string): Promise<number> {
79	    isolationState.pipeCalls.push(this.errorMessage);
80	    await new Promise(resolve => setTimeout(resolve, this.delayMs));
81	    const parsed = Number(value);
82	    if (Number.isNaN(parsed) || value.trim() === '') {
83	      throw new BadRequestException(this.errorMessage);
84	    }
85	    return parsed;
86	  }
87	}
88	
89	// The limit chain runs after a DefaultValuePipe, so its input is either the
90	// raw query string or the seeded default number. Explicit invalid values must
91	// fail the chain (LIMIT) instead of silently falling back to the default.
92	class LimitPipe implements PipeTransform<string | number, number> {
93	  transform(value: string | number): number {
94	    isolationState.pipeCalls.push('LIMIT');
95	    if (typeof value === 'string' && value.trim() === '') {
96	      throw new BadRequestException('LIMIT');
97	    }
98	    const parsed = Number(value);
99	    if (Number.isNaN(parsed)) {
100	      throw new BadRequestException('LIMIT');
101	    }
102	    return parsed;
103	  }
104	}
105	
106	class SlowLimitPipe implements PipeTransform<
107	  string | number,
108	  Promise<number> | number
109	> {
110	  constructor(private readonly delayMs: number) {}
111	
112	  async transform(value: string | number): Promise<number> {
113	    isolationState.pipeCalls.push('LIMIT');
114	    await new Promise(resolve => setTimeout(resolve, this.delayMs));
115	    if (typeof value === 'string' && value.trim() === '') {
116	      throw new BadRequestException('LIMIT');
117	    }
118	    const parsed = Number(value);
119	    if (Number.isNaN(parsed)) {
120	      throw new BadRequestException('LIMIT');
121	    }
122	    return parsed;
123	  }
124	}
125	
126	// `currency` is a required query parameter: a missing or blank value is a
127	// request error (CURRENCY), never masked by the optional `limit` default.
128	class CurrencyPipe implements PipeTransform<string | undefined, string> {
129	  transform(value: string | undefined): string {
130	    isolationState.pipeCalls.push('CURRENCY');
131	    if (value === undefined || value.trim() === '') {
132	      throw new BadRequestException('CURRENCY');
133	    }
134	    return value.toUpperCase();
135	  }
136	}
137	
138	// Upper bound (inclusive) of the decimal range accepted by the batch routes.
139	const MAX_BATCH_VALUE = 2147483647;
140	
141	// Strict decimal conversion shared by the batch routes: only non-empty values
142	// consisting solely of ASCII digits and converting to an integer between 0
143	// and 2147483647 (inclusive) are accepted. Scientific notation, hex, signs,
144	// whitespace padding and fractional input all fail; leading zeros convert
145	// normally ('004' -> 4).
146	function parseBatchValue(raw: unknown): number | null {
147	  if (typeof raw !== 'string' || !/^[0-9]+$/.test(raw)) {
148	    return null;
149	  }
150	  const parsed = Number(raw);
151	  if (!Number.isInteger(parsed) || parsed > MAX_BATCH_VALUE) {
152	    return null;
153	  }
154	  return parsed;
155	}
156	
157	// An invalid batch id is not a parameter-validation error to be aggregated:
158	// it aborts the whole request immediately (before any item is inspected) with
159	// a plain single-message 400 body, so it must not be collected into the
160	// aggregated message array of the annotated route.
161	class InvalidBatchIdException extends HttpException {
162	  constructor() {
163	    super(
164	      {
165	        statusCode: HttpStatus.BAD_REQUEST,
166	        error: 'Bad Request',
167	        message: 'ID',
168	      },
169	      HttpStatus.BAD_REQUEST,
170	    );
171	  }
172	}
173	
174	class BatchIdPipe implements PipeTransform<string, number> {
175	  transform(value: string): number {
176	    const parsed = parseBatchValue(value);
177	    if (parsed === null) {
178	      throw new InvalidBatchIdException();
179	    }
180	    return parsed;
181	  }
182	}
183	
184	// The id is validated before any parameter pipe runs (guards execute ahead of
185	// pipes on annotated and unannotated routes alike), so an invalid id always
186	// aborts the request with the plain 'ID' 400 and no item is ever inspected -
187	// regardless of the order in which concurrent parameter pipes would settle.
188	@Injectable()
189	class BatchIdGuard implements CanActivate {
190	  canActivate(context: ExecutionContext): boolean {
191	    isolationState.pipeCalls.push('ID');
192	    const request = context.switchToHttp().getRequest();
193	    const parsed = parseBatchValue(request.params?.id);
194	    if (parsed === null) {
195	      throw new InvalidBatchIdException();
196	    }
197	    return true;
198	  }
199	}
200	
201	// Converts a repeatable `item` query key (`?item=2&item=4`) one element at a
202	// time, in appearance order. Conversion errors are aggregated and stay
203	// indexable (ITEM[0], ITEM[2], ...); `deny` is not a request-parameter error
204	// but a conflict that aborts the resolution immediately.
205	class BatchItemsPipe implements PipeTransform<
206	  string[] | string | undefined,
207	  number[]
208	> {
209	  transform(value: string[] | string | undefined): number[] {
210	    if (value === undefined) {
211	      // The key is entirely absent: one unindexed message, distinct from an
212	      // explicit empty value (which exists as element 0 and fails as ITEM[0]).
213	      isolationState.pipeCalls.push('ITEM');
214	      throw new BadRequestException(['ITEM']);
215	    }
216	    const items = Array.isArray(value) ? value : [value];
217	    const numbers: number[] = [];
218	    const messages: string[] = [];
219	    items.forEach((raw, index) => {
220	      isolationState.pipeCalls.push('ITEM');
221	      if (raw === 'deny') {
222	        // Non-request error: stop touching the remaining elements and abort
223	        // the whole parameter resolution; messages staged earlier are dropped.
224	        throw new ConflictException('DENIED');
225	      }
226	      const parsed = parseBatchValue(raw);
227	      if (parsed === null) {
228	        messages.push(`ITEM[${index}]`);
229	        return;
230	      }
231	      numbers.push(parsed);
232	    });
233	    if (messages.length > 0) {
234	      throw new BadRequestException(messages);
235	    }
236	    return numbers;
237	  }
238	}
239	
240	class NotFoundPipe implements PipeTransform<string, string> {
241	  transform(value: string): string {
242	    isolationState.pipeCalls.push('N');
243	    if (value === 'missing') {
244	      throw new NotFoundException('NOT-FOUND');
245	    }
246	    return value;
247	  }
248	}
249	
250	class PartialAbortPipe implements PipeTransform<string, string> {
251	  transform(value: string): string {
252	    isolationState.pipeCalls.push('M');
253	    if (value === 'abort') {
254	      // A non-BadRequest HttpException: aggregation must abort immediately and
255	      // the default exception layer keeps its regular status/body path.
256	      throw new ForbiddenException('ABORTED');
257	    }
258	    return value;
259	  }
260	}
261	
262	class BodyPipe implements PipeTransform<any, any> {
263	  transform(body: any): any {
264	    isolationState.pipeCalls.push('BODY');
265	    if (!body || body.valid !== true) {
266	      throw new BadRequestException('BODY');
267	    }
268	    return { ...body, transformed: true };
269	  }
270	}
271	
272	class CustomUserPipe implements PipeTransform<any, any> {
273	  transform(user: any): any {
274	    isolationState.pipeCalls.push('CUSTOM');
275	    if (!user || user.ok !== true) {
276	      throw new BadRequestException('CUSTOM');
277	    }
278	    return user;
279	  }
280	}
281	
282	class HeaderNumberPipe implements PipeTransform<string | undefined, number> {
283	  transform(value: string | undefined): number {
284	    isolationState.pipeCalls.push('H');
285	    const parsed = Number(value);
286	    if (
287	      value === undefined ||
288	      String(value).trim() === '' ||
289	      Number.isNaN(parsed)
290	    ) {
291	      throw new BadRequestException('H');
292	    }
293	    return parsed;
294	  }
295	}
296	
297	class HeaderAbortPipe implements PipeTransform<string | undefined, string> {
298	  transform(value: string | undefined): string {
299	    isolationState.pipeCalls.push('HF');
300	    if (value === 'abort') {
301	      // A non-BadRequest exception raised by a header pipe: aggregation must
302	      // abort immediately and the staged param/query messages are discarded.
303	      throw new ForbiddenException('HEADER-ABORT');
304	    }
305	    return value ?? '';
306	  }
307	}
308	
309	// Fail-fast counterpart used by the unannotated compatibility route: it stops
310	// at the first non-convertible element and throws one plain (single) error,
311	// mirroring the legacy short-circuit semantics of any ordinary parameter pipe.
312	class BatchItemsFailFastPipe implements PipeTransform<
313	  string[] | string | undefined,
314	  number[]
315	> {
316	  transform(value: string[] | string | undefined): number[] {
317	    if (value === undefined) {
318	      throw new BadRequestException('ITEM');
319	    }
320	    const items = Array.isArray(value) ? value : [value];
321	    const numbers: number[] = [];
322	    for (let index = 0; index < items.length; index++) {
323	      isolationState.pipeCalls.push('ITEM');
324	      const raw = items[index];
325	      if (raw === 'deny') {
326	        throw new ConflictException('DENIED');
327	      }
328	      const parsed = parseBatchValue(raw);
329	      if (parsed === null) {
330	        throw new BadRequestException(`ITEM[${index}]`);
331	      }
332	      numbers.push(parsed);
333	    }
334	    return numbers;
335	  }
336	}
337	
338	const User = createParamDecorator((_data: unknown, ctx: ExecutionContext) => {
339	  const request = ctx.switchToHttp().getRequest();
340	  const name = request.headers['x-user'];
341	  return name ? { name, ok: true } : { ok: false };
342	});
343	
344	@Catch(BadRequestException)
345	export class MyParamFilter implements ExceptionFilter {
346	  public static received: Array<{
347	    status: number;
348	    message: unknown;
349	  }> = [];
350	
351	  constructor(private readonly adapterHost: HttpAdapterHost) {}
352	
353	  catch(exception: BadRequestException, host: ArgumentsHost) {
354	    const { httpAdapter } = this.adapterHost;
355	    const response = host.switchToHttp().getResponse();
356	    const responseBody = exception.getResponse() as { message: unknown };
357	    // Record every invocation so tests can assert the filter sees the
358	    // aggregated exception exactly once (never per-parameter exceptions).
359	    MyParamFilter.received.push({
360	      status: exception.getStatus(),
361	      message: responseBody.message,
362	    });
363	    const count = Array.isArray(responseBody.message)
364	      ? responseBody.message.length
365	      : 1;
366	    httpAdapter.reply(response, { code: 'PARAMS_INVALID', count }, 422);
367	  }
368	}
369	
370	@Catch()
371	export class MyWideFilter implements ExceptionFilter {
372	  public static last: { name: string; status?: number } | null = null;
373	
374	  constructor(private readonly adapterHost: HttpAdapterHost) {}
375	
376	  catch(exception: unknown, host: ArgumentsHost) {
377	    const { httpAdapter } = this.adapterHost;
378	    const response = host.switchToHttp().getResponse();
379	    MyWideFilter.last = {
380	      name: (exception as Error)?.name,
381	      status:
382	        typeof (exception as { getStatus?: () => number })?.getStatus ===
383	        'function'
384	          ? (exception as { getStatus: () => number }).getStatus()
385	          : undefined,
386	    };
387	    httpAdapter.reply(response, { code: 'WIDE' }, 418);
388	  }
389	}
390	
391	@Controller('p')
392	export class AggregateParamErrorsController {
393	  @AggregateParamErrors()
394	  @Get(':id')
395	  public aggregated(
396	    @Param('id', new NumberPipe('A')) id: number,
397	    @Query('limit', new NumberPipe('B')) limit: number,
398	  ) {
399	    recordHandler('aggregated');
400	    return `${id},${limit}`;
401	  }
402	
403	  @Get('legacy/:id')
404	  public legacy(
405	    @Param('id', new NumberPipe('A')) id: number,
406	    @Query('limit', new NumberPipe('B')) limit: number,
407	  ) {
408	    recordHandler('legacy');
409	    return `${id},${limit}`;
410	  }
411	
412	  @AggregateParamErrors()
413	  @UseFilters(MyParamFilter)
414	  @Get('filtered/:id')
415	  public filtered(
416	    @Param('id', new NumberPipe('A')) id: number,
417	    @Query('limit', new NumberPipe('B')) limit: number,
418	  ) {
419	    recordHandler('filtered');
420	    return `${id},${limit}`;
421	  }
422	
423	  @AggregateParamErrors()
424	  @Get('other/:id')
425	  public other(
426	    @Param('id', new NotFoundPipe()) id: string,
427	    @Query('limit', new NumberPipe('B')) limit: number,
428	  ) {
429	    recordHandler('other');
430	    return `${id},${limit}`;
431	  }
432	
433	  // The first @Param() fails with a BadRequest (collected), the second
434	  // @Param() aborts with a non-BadRequest error: the partially collected
435	  // message must die with this request.
436	  @AggregateParamErrors()
437	  @Get('partial/:id/:mode')
438	  public partial(
439	    @Param('id', new NumberPipe('A')) id: number,
440	    @Param('mode', new PartialAbortPipe()) mode: string,
441	    @Query('limit', new NumberPipe('B')) limit: number,
442	  ) {
443	    recordHandler('partial');
444	    return `${id},${mode},${limit}`;
445	  }
446	
447	  // Delayed param pipe used to keep a valid and an invalid request genuinely
448	  // in flight at the same time in the parallel tests.
449	  @AggregateParamErrors()
450	  @Get('slow/:id')
451	  public slow(
452	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
453	    @Query('limit', new NumberPipe('B')) limit: number,
454	  ) {
455	    recordHandler('slow');
456	    return `${id},${limit}`;
457	  }
458	
459	  // @Body() must stay outside the aggregation scope: its pipe error aborts
460	  // immediately even when a @Param() failed first.
461	  @AggregateParamErrors()
462	  @Post('body/:id')
463	  public withBody(
464	    @Param('id', new NumberPipe('A')) id: number,
465	    @Body(new BodyPipe()) body: { transformed: boolean },
466	    @Query('limit', new NumberPipe('B')) limit: number,
467	  ) {
468	    recordHandler('body');
469	    return `${id},${limit},${body.transformed ? 'transformed' : 'raw'}`;
470	  }
471	
472	  // Custom parameter extractors must keep the existing (fail-fast) scope.
473	  @AggregateParamErrors()
474	  @Get('custom/:id')
475	  public withCustom(
476	    @Param('id', new NumberPipe('A')) id: number,
477	    @User(new CustomUserPipe()) user: { name: string },
478	    @Query('limit', new NumberPipe('B')) limit: number,
479	  ) {
480	    recordHandler('custom');
481	    return `${id},${limit},${user.name}`;
482	  }
483	
484	  // @Headers() parameters are an independent input domain: the header pipe
485	  // always runs and its transformed value reaches the handler, but a header
486	  // failure aborts the resolution immediately and discards any @Param()/
487	  // @Query() messages collected so far.
488	  @AggregateParamErrors()
489	  @Get('headers/:id')
490	  public withHeaders(
491	    @Param('id', new NumberPipe('A')) id: number,
492	    @Headers('x-token', new HeaderNumberPipe()) token: number,
493	    @Query('limit', new NumberPipe('B')) limit: number,
494	  ) {
495	    recordHandler('headers');
496	    return `${id},${token},${limit}`;
497	  }
498	
499	  // The filter must observe only the header exception when the header pipe
500	  // fails - never the staged @Param()/@Query() messages.
501	  @AggregateParamErrors()
502	  @UseFilters(MyParamFilter)
503	  @Get('headers-filtered/:id')
504	  public withHeadersFiltered(
505	    @Param('id', new NumberPipe('A')) id: number,
506	    @Headers('x-token', new HeaderNumberPipe()) token: number,
507	    @Query('limit', new NumberPipe('B')) limit: number,
508	  ) {
509	    recordHandler('headersFiltered');
510	    return `${id},${token},${limit}`;
511	  }
512	
513	  // A non-BadRequest header exception propagates unchanged through the
514	  // catch-all filter; the staged param/query messages die with the request.
515	  @AggregateParamErrors()
516	  @UseFilters(MyWideFilter)
517	  @Get('headers-wide/:id')
518	  public withHeadersWide(
519	    @Param('id', new NumberPipe('A')) id: number,
520	    @Headers('x-mode', new HeaderAbortPipe()) mode: string,
521	    @Query('limit', new NumberPipe('B')) limit: number,
522	  ) {
523	    recordHandler('headersWide');
524	    return `${id},${mode},${limit}`;
525	  }
526	
527	  // Unannotated route with a header pipe: the header pipe runs, but the
528	  // fail-fast compatibility path is unchanged.
529	  @Get('headers-legacy/:id')
530	  public withHeadersLegacy(
531	    @Param('id', new NumberPipe('A')) id: number,
532	    @Headers('x-token', new HeaderNumberPipe()) token: number,
533	    @Query('limit', new NumberPipe('B')) limit: number,
534	  ) {
535	    recordHandler('headersLegacy');
536	    return `${id},${token},${limit}`;
537	  }
538	
539	  // Delayed pipes on all three domains, used to keep mixed-failure requests
540	  // genuinely in flight at the same time in the parallel tests.
541	  @AggregateParamErrors()
542	  @Get('headers-slow/:id')
543	  public withHeadersSlow(
544	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
545	    @Headers('x-token', new SlowNumberPipe('H', 30)) token: number,
546	    @Query('limit', new SlowNumberPipe('B', 30)) limit: number,
547	  ) {
548	    recordHandler('headersSlow');
549	    return `${id},${token},${limit}`;
550	  }
551	
552	  // A catch-all method filter must receive the original non-request exception
553	  // unchanged (not the aggregated BadRequest).
554	  @AggregateParamErrors()
555	  @UseFilters(MyWideFilter)
556	  @Get('wide/:id')
557	  public wide(
558	    @Param('id', new NotFoundPipe()) id: string,
559	    @Query('limit', new NumberPipe('B')) limit: number,
560	  ) {
561	    recordHandler('wide');
562	    return `${id},${limit}`;
563	  }
564	
565	  // Optional query value with a per-resolution default: when `limit` is
566	  // absent, DefaultValuePipe seeds 10 which still runs through the same
567	  // LimitPipe conversion as an explicit value. An explicit invalid value
568	  // must fail (LIMIT), never fall back to 10. `currency` is required.
569	  @AggregateParamErrors()
570	  @Get('defaults/:id')
571	  public defaults(
572	    @Param('id', new NumberPipe('A')) id: number,
573	    @Query('currency', new CurrencyPipe()) currency: string,
574	    @Query('limit', new DefaultValuePipe(10), new LimitPipe())
575	    limit: number,
576	  ) {
577	    recordHandler('defaults');
578	    return { id, currency, limit };
579	  }
580	
581	  // Delayed variant of the defaults route used to keep a default-success and
582	  // an explicit-invalid request genuinely in flight in the parallel tests.
583	  @AggregateParamErrors()
584	  @Get('defaults-slow/:id')
585	  public defaultsSlow(
586	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
587	    @Query('currency', new CurrencyPipe()) currency: string,
588	    @Query('limit', new DefaultValuePipe(10), new SlowLimitPipe(30))
589	    limit: number,
590	  ) {
591	    recordHandler('defaultsSlow');
592	    return { id, currency, limit };
593	  }
594	}
595	
596	// Root-level controller for the repeatable-query-key batch routes. The marked
597	// route aggregates the per-element conversion feedback of a single request;
598	// the unannotated route keeps the legacy fail-fast short-circuit for contrast.
599	// On both routes an invalid id aborts the request immediately with a plain
600	// single-message 400 ('ID') before any item is inspected.
601	@Controller()
602	@UseGuards(BatchIdGuard)
603	export class BatchController {
604	  @AggregateParamErrors()
605	  @Get('batch/:id')
606	  public batch(
607	    @Param('id', new BatchIdPipe()) id: number,
608	    @Query('item', new BatchItemsPipe()) items: number[],
609	  ) {
610	    recordHandler('batch');
611	    return { id, items };
612	  }
613	
614	  @Get('batch-plain/:id')
615	  public batchPlain(
616	    @Param('id', new BatchIdPipe()) id: number,
617	    @Query('item', new BatchItemsFailFastPipe()) items: number[],
618	  ) {
619	    recordHandler('batchPlain');
620	    return { id, items };
621	  }
622	}
