2	import {
3	  isolationState,
4	  MyParamFilter,
5	  MyWideFilter,
6	  resetIsolationState,
7	} from '../src/aggregate-param-errors.controller.js';
8	
9	export interface IsolationResponse {
10	  status: number;
11	  body: any;
12	  text: string;
13	}
14	
15	export interface RequestOptions {
16	  body?: unknown;
17	  headers?: Record<string, string>;
18	}
19	
20	export interface IsolationSuiteDeps {
21	  readonly platformName: string;
22	  createApp(): Promise<{
23	    app: INestApplication;
24	    request: (
25	      method: 'GET' | 'POST',
26	      path: string,
27	      options?: RequestOptions,
28	    ) => Promise<IsolationResponse>;
29	    close: () => Promise<void>;
30	  }>;
31	}
32	
33	/**
34	 * Sequences, failure boundaries and parallel-execution assertions shared
35	 * verbatim by the Express and Fastify adapters: both platforms must expose
36	 * exactly the same per-request isolation behaviour.
37	 */
38	export function registerIsolationSuite(deps: IsolationSuiteDeps): void {
39	  type SendRequest = (
40	    method: 'GET' | 'POST',
41	    path: string,
42	    options?: RequestOptions,
43	  ) => Promise<IsolationResponse>;
44	  let request: SendRequest;
45	  let close: () => Promise<void>;
46	
47	  beforeEach(async () => {
48	    const harness = await deps.createApp();
49	    request = harness.request;
50	    close = harness.close;
51	    resetIsolationState();
52	  });
53	
54	  afterEach(async () => {
55	    await close();
56	  });
57	
58	  describe(`[${deps.platformName}] per-request isolation`, () => {
59	    describe('sequential requests on an annotated route', () => {
60	      it('re-runs every pipe on a valid request after a double-error and calls the handler once with transformed values', async () => {
61	        const failed = await request('GET', '/p/abc?limit=x');
62	        expect(failed.status).toBe(400);
63	        expect(failed.body).toEqual({
64	          statusCode: 400,
65	          error: 'Bad Request',
66	          message: ['A', 'B'],
67	        });
68	        expect(isolationState.handlerCalls.aggregated ?? 0).toBe(0);
69	        expect(isolationState.pipeCalls).toEqual(['A', 'B']);
70	
71	        const ok = await request('GET', '/p/7?limit=10');
72	        expect(ok.status).toBe(200);
73	        expect(ok.text).toBe('7,10');
74	        // Both pipes of the second request ran again, in declaration order.
75	        expect(isolationState.pipeCalls).toEqual(['A', 'B', 'A', 'B']);
76	        expect(isolationState.handlerCalls.aggregated).toBe(1);
77	      });
78	
79	      it("reports only this request's messages on a double-error after a valid request (reverse order)", async () => {
80	        const ok = await request('GET', '/p/7?limit=10');
81	        expect(ok.status).toBe(200);
82	        expect(ok.text).toBe('7,10');
83	        expect(isolationState.handlerCalls.aggregated).toBe(1);
84	
85	        const failed = await request('GET', '/p/abc?limit=x');
86	        expect(failed.status).toBe(400);
87	        expect(failed.body).toEqual({
88	          statusCode: 400,
89	          error: 'Bad Request',
90	          message: ['A', 'B'],
91	        });
92	        // The handler ran only for the valid request; the message array was
93	        // not carried over from (or duplicated by) the first request.
94	        expect(isolationState.handlerCalls.aggregated).toBe(1);
