import { describe, expect, it } from 'vitest';
import { Test } from '@nestjs/testing';
import { AggregateParamErrorsModule } from '../src/aggregate-param-errors.module.js';
import {
  FastifyAdapter,
  NestFastifyApplication,
} from '@nestjs/platform-fastify';

describe('prototype gates', () => {
  function badIdBody() {
    return {
      statusCode: 400,
      error: 'Bad Request',
      message: 'ID',
    };
  }

  it('express pre-init middleware gates malformed percent', async () => {
    const moduleRef = await Test.createTestingModule({
      imports: [AggregateParamErrorsModule],
    }).compile();
    const app = moduleRef.createNestApplication();
    const instance = app.getHttpAdapter().getInstance();
    instance.use((req: any, res: any, next: any) => {
      const q = req.url.indexOf('?');
      const pathname = q === -1 ? req.url : req.url.slice(0, q);
      const m = /^\/batch(?:-plain)?\/([^/]+)\/?$/.exec(pathname);
      if (m) {
        try {
          decodeURIComponent(m[1]);
        } catch {
          return res.status(400).json(badIdBody());
        }
      }
      next();
    });
    const server = await app.listen(0);
    const r1 = await fetch(
      `http://127.0.0.1:${(server.address() as any).port}/batch/%ZZ?item=1`,
    );
    console.log('express %ZZ', r1.status, await r1.text());
    const r2 = await fetch(
      `http://127.0.0.1:${(server.address() as any).port}/batch/%37?item=1`,
    );
    console.log('express %37', r2.status, await r2.text());
    const r3 = await fetch(
      `http://127.0.0.1:${(server.address() as any).port}/batch/%FF?item=deny`,
    );
    console.log('express %FF deny', r3.status, await r3.text());
    const r4 = await fetch(
      `http://127.0.0.1:${(server.address() as any).port}/p/%FF?limit=x`,
    );
    console.log('express /p/%FF unchanged', r4.status, await r4.text());
    await app.close();
    expect(true).toBe(true);
  });

  it('fastify frameworkErrors gates malformed percent', async () => {
    const moduleRef = await Test.createTestingModule({
      imports: [AggregateParamErrorsModule],
    }).compile();
    const app = moduleRef.createNestApplication<NestFastifyApplication>(
      new FastifyAdapter({
        frameworkErrors: (error: any, req: any, reply: any) => {
          console.log('frameworkErrors raw url:', req.url, req.raw?.url);
          if (error.code === 'FST_ERR_BAD_URL') {
            const raw = req.url ?? req.raw?.url ?? '';
            const q = raw.indexOf('?');
            const pathname = q === -1 ? raw : raw.slice(0, q);
            if (/^\/batch(?:-plain)?\/[^/]+/.test(pathname)) {
              return reply.code(400).send(badIdBody());
            }
          }
          return reply.code(400).send({
            error: 'Bad Request',
            code: error.code,
            message: error.message,
            statusCode: 400,
          });
        },
      }),
    );
    await app.init();
    await app.getHttpAdapter().getInstance().ready();
    const r1 = await app.inject({ method: 'GET', url: '/batch/%ZZ?item=1' });
    console.log('fastify %ZZ', r1.statusCode, r1.payload);
    const r2 = await app.inject({ method: 'GET', url: '/batch/%37?item=1' });
    console.log('fastify %37', r2.statusCode, r2.payload);
    const r3 = await app.inject({
      method: 'GET',
      url: '/batch/%FF?item=deny',
    });
    console.log('fastify %FF deny', r3.statusCode, r3.payload);
    const r4 = await app.inject({ method: 'GET', url: '/p/%FF?limit=x' });
    console.log('fastify /p/%FF default', r4.statusCode, r4.payload);
    await app.close();
    expect(true).toBe(true);
  });
});

