import { createAggregateParamErrorsApp } from '../src/create-aggregate-param-errors-app.js';

const probes: Array<[string, string]> = [
  ['bracket array', '/batch/7?item[]=1&item[]=2'],
  ['indexed brackets', '/batch/7?item[0]=1&item[1]=2'],
  ['comma', '/batch/7?item=1,2'],
  ['semicolon separator', '/batch/7?item=1;item=2'],
  ['empty pair between', '/batch/7?item=1&&item=2'],
  ['equals inside', '/batch/7?item=a=b'],
  ['duplicate other key', '/batch/7?tag=a&tag=b&item=1&item=2'],
  ['item interleave complex', '/batch/7?item=1&tag=a&item=2&tag=b&item=3'],
  ['invalid utf8 item', '/batch/7?item=%FF'],
  ['invalid utf8 id', '/batch/%FF?item=1'],
  ['overlong utf8 item', '/batch/7?item=%C0%80'],
  ['mixed good bad escape item', '/batch/7?item=7%37%ZZ'],
  ['bad percent then valid item', '/batch/7?item=%&item=1'],
  ['encoded bracket', '/batch/7?item=%5B%5D'],
  ['plus encoded deny mix', '/batch/7?item=de%6ey'],
  ['encoded deny after invalid id utf8', '/batch/%FF?item=deny'],
  ['tab encoded', '/batch/7?item=%091'],
  ['encoded null between digits', '/batch/7?item=1%002'],
];

for (const adapter of ['express', 'fastify'] as const) {
  describe(`probe ${adapter}`, () => {
    for (const [label, url] of probes) {
      it(label, async () => {
        const app = await createAggregateParamErrorsApp(adapter);
        const res = await app.get(url);
        console.log(
          adapter,
          label,
          JSON.stringify(url),
          '->',
          res.status,
          JSON.stringify(res.body),
        );
        await app.close();
        expect(true).toBe(true);
      });
    }
  });
}

