364	  describe(`[${deps.platformName}] query/path decoding boundary`, () => {
365	    it.each(aggregatedCases)('$label', async ({ path, expected }) => {
366	      const response = await request('GET', path);
367	      expect(response.status).toBe(expected.status);
368	      expect(response.body).toEqual(expected.body);
369	    });
370	
371	    it.each(guardRejectedIdCases)(
372	      'id: $label fails via the id guard without inspecting items',
373	      async ({ path, expected }) => {
374	        const response = await request('GET', path);
375	        expect(response.status).toBe(expected.status);
376	        expect(response.body).toEqual(expected.body);
377	        expect(isolationState.pipeCalls).toEqual(['ID']);
378	        expect(isolationState.handlerCalls.batch ?? 0).toBe(0);
379	      },
380	    );
381	
382	    it.each(gateRejectedIdCases)(
383	      'id: $label is rejected before routing without a 500',
384	      async ({ path, expected }) => {
385	        const response = await request('GET', path);
386	        expect(response.status).toBe(expected.status);
387	        expect(response.body).toEqual(expected.body);
388	        expect(isolationState.pipeCalls).toEqual([]);
389	        expect(isolationState.handlerCalls.batch ?? 0).toBe(0);
390	      },
391	    );
392	
393	    it.each(plainCases)('compat: $label', async ({ path, expected }) => {
394	      const response = await request('GET', path);
395	      expect(response.status).toBe(expected.status);
396	      expect(response.body).toEqual(expected.body);
397	    });
398	
399	    it('keeps encoded parameters on non-batch routes working', async () => {
400	      const response = await request('GET', '/p/%37?limit=%31%30');
401	      expect(response.status).toBe(200);
402	      expect(response.text).toBe('7,10');
403	    });
404	
405	    it('still answers a malformed percent on a non-batch route with a 400 (not a 500)', async () => {
406	      const response = await request('GET', '/p/%FF?limit=10');
407	      expect(response.status).toBe(400);
408	      expect(isolationState.handlerCalls.aggregated ?? 0).toBe(0);
409	    });
410	
411	    it('decides every response from its own request in an encoded sequence', async () => {
412	      const success = await request('GET', '/batch/%37?item=%32&item=004');
413	      expect(success.status).toBe(200);
414	      expect(success.body).toEqual({ id: 7, items: [2, 4] });
415	
416	      const elementError = await request('GET', '/batch/7?item=%');
417	      expect(elementError.body).toEqual(badRequest(['ITEM[0]']));
418	
419	      const conflict = await request(
420	        'GET',
421	        '/batch/7?item=x&item=%64%65%6e%79&item=y',
422	      );
423	      expect(conflict.status).toBe(409);
424	      expect(conflict.body).toEqual(denied());
425	
426	      const successAgain = await request(
427	        'GET',
428	        '/batch/7?item=2&tag=x&item=004',
429	      );
430	      expect(successAgain.body).toEqual({ id: 7, items: [2, 4] });
431	
432	      expect(isolationState.handlerCalls.batch).toBe(2);
433	      expect(isolationState.pipeCalls).toEqual([
434	        'ID',
435	        'ITEM',
436	        'ITEM',
437	        'ID',
438	        'ITEM',
439	        'ID',
440	        'ITEM',
441	        'ITEM',
442	        'ID',
443	        'ITEM',
444	        'ITEM',
445	      ]);
446	
447	      // Nothing leaked into a subsequent request.
448	      const clean = await request('GET', '/batch/8?item=5');
449	      expect(clean.body).toEqual({ id: 8, items: [5] });
450	      expect(isolationState.handlerCalls.batch).toBe(3);
451	    });
452	
453	    it('keeps parallel encoded success, element-error and deny requests isolated', async () => {
454	      const [first, second, elementError, conflict] = await Promise.all([
455	        request('GET', '/batch/7?item=%32&item=004'),
456	        request('GET', '/batch/7?item=%32&item=004'),
457	        request('GET', '/batch/7?item=1&item=%&item=2'),
458	        request('GET', '/batch/7?item=%64%65%6e%79'),
459	      ]);
460	
461	      for (const response of [first, second]) {
462	        expect(response.status).toBe(200);
463	        expect(response.body).toEqual({ id: 7, items: [2, 4] });
464	      }
465	      expect(elementError.status).toBe(400);
466	      expect(elementError.body).toEqual(badRequest(['ITEM[1]']));
467	      expect(conflict.status).toBe(409);
468	      expect(conflict.body).toEqual(denied());
469	
470	      // Exactly the two successful requests reached the handler.
471	      expect(isolationState.handlerCalls.batch).toBe(2);
472	      expect(isolationState.pipeCalls.filter(tag => tag === 'ID')).toHaveLength(
473	        4,
474	      );
475	      expect(
476	        isolationState.pipeCalls.filter(tag => tag === 'ITEM'),
477	      ).toHaveLength(8);
478	
479	      const clean = await request('GET', '/batch/8?item=5');
480	      expect(clean.body).toEqual({ id: 8, items: [5] });
481	      expect(isolationState.handlerCalls.batch).toBe(3);
482	    });
483	  });
484	}
